import json, subprocess, sys

def call(method, data):
    cmd = ["curl", "-s", f"https://slack.com/api/{method}", "-d", "token=<TOKEN>"]
    for k, v in data.items():
        cmd += ["-d", f"{k}={v}"]
    out = subprocess.run(cmd, capture_output=True, text=True).stdout
    return json.loads(out)

d = call("users.list", {})
for u in d.get("members", []):
    if u.get("deleted"):
        continue
    profile = u.get("profile", {})
    hay = " ".join(str(x) for x in [profile.get("real_name", ""), u.get("name", ""), u.get("username", ""), profile.get("display_name", "")]).lower()
    if "priya" in hay:
        print(u.get("id"), "|", profile.get("real_name"), "|", u.get("name"), "|", u.get("username"))

